// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target, uint256 value) internal {
        vm.assume(true);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(target, value) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assertTrue(!reverted ? balBefore - balAfter == value : true);
    }

    function testFuzz_run(address target, uint256 value) public {
        _run(target, value);
    }

    receive() external payable {}
}
